class ExperimentCosts(
    RootModel[ExperimentCosts1 | ExperimentCosts2 | ExperimentCosts3 | ExperimentCosts4]
):
    root: ExperimentCosts1 | ExperimentCosts2 | ExperimentCosts3 | ExperimentCosts4 = (
        Field(
            ...,
            description='Dynamic cost information for an experiment.\n\nRepresents the current cost state based on experiment lifecycle:\n- `Estimate`: Computed from experiment spec (no Stripe quote yet)\n- `Quoted`: Real quote from Stripe (awaiting acceptance)\n- `Invoiced`: Invoice created (payment pending or complete)\n\nResolution order: If `stripe_invoice_url` exists, returns `Invoiced`. Otherwise,\nif `stripe_quote_url` exists, returns `Quoted`. Otherwise computes `Estimate`.',
        )
    )


