class CreateExpRequest(BaseModel):
    auto_accept_quote: bool = Field(
        False,
        description='Auto-accept the quote and create an invoice (without sending).\n\nWhen `true`, the system will:\n1. Create a Stripe quote (requires target_id and full pricing available)\n2. Finalize and accept the quote\n3. Create a draft invoice (not sent to customer)\n4. Advance the experiment to "Waiting for materials" status\n\nThis enables fully automated experiment submission pipelines where payment\nis handled externally or the organization has pre-approved billing.\nImplies `skip_draft: true`.',
    )
    experiment_spec: ExperimentSpec = Field(
        ...,
        description='Structured experiment definition (type, target, sequences, parameters)',
    )
    name: str = Field(
        ...,
        description='Human-readable name for the experiment',
        examples=['PD-L1 affinity panel'],
    )
    skip_draft: bool | None = Field(
        None,
        description='Bypass Draft status and submit directly for processing.\n\nWhen `true`, the experiment is created in "Waiting for confirmation"\nstatus instead of Draft, skipping the manual review step. Use this for\nautomated pipelines with pre-validated payloads.\n\nWhen an experiment is submitted with `skip_draft: true` and the target\nhas existing inventory materials, those materials are automatically\nlinked to expedite processing.',
    )
    webhook_url: str | None = Field(
        None,
        description='URL to which experiment status updates will be POSTed',
        examples=['https://example.com/webhook'],
    )


